ALTER TABLE public.schools
ADD COLUMN result_sheet_config jsonb NOT NULL DEFAULT '{"version":1,"schoolTitle":"{{school}}","documentTitle":"{{session}} 投票结果确认单","summaryTemplate":"应到评委 {{judgeCount}} 人，实际提交 {{submitted}} 人。","description":"","columns":[{"key":"index","label":"序号","visible":true},{"key":"name","label":"姓名","visible":true},{"key":"unit","label":"单位","visible":true},{"key":"title","label":"现职称","visible":true},{"key":"recommend","label":"推荐","visible":true},{"key":"not_recommend","label":"不推荐","visible":true},{"key":"abstain","label":"弃权","visible":true}],"signatures":[{"id":"chair","label":"主任委员签字","lines":1,"showDate":true},{"id":"members","label":"其他委员签字","lines":3,"showDate":false},{"id":"supervisor","label":"监票人签字","lines":1,"showDate":true}],"orientation":"portrait","fontSize":"medium","density":"comfortable","footer":""}'::jsonb;

COMMENT ON COLUMN public.schools.result_sheet_config IS 'School-wide result confirmation sheet template configuration';